#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

extern void sha256_multi_block(void *ctx, const void *inp, int num);

typedef struct { const unsigned char *ptr; int blocks; int pad; } Desc;

static uint32_t IV[8] = {
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
};

static double now() {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

int main() {
    size_t msg = 20ull*1024*1024; // not necessarily multiple of 64
    // We'll hash 8 independent messages of this size using multi-block + padding
    int lanes = 8;
    // padded length: msg + 1 + pad + 8, multiple of 64
    size_t bitlen_field = 8;
    size_t with_one = msg + 1;
    size_t pad = (64 - ((with_one + bitlen_field) % 64)) % 64;
    size_t total = with_one + pad + bitlen_field;
    int blocks = (int)(total / 64);
    printf("msg %zu padded %zu blocks %d\n", msg, total, blocks);

    unsigned char *bufs[8];
    for (int i = 0; i < lanes; i++) {
        bufs[i] = aligned_alloc(64, total + 64);
        memset(bufs[i], 0, total);
        memset(bufs[i], 0x41 + i, msg);
        bufs[i][msg] = 0x80;
        // length in bits big-endian at end
        uint64_t bits = (uint64_t)msg * 8;
        for (int b = 0; b < 8; b++)
            bufs[i][total - 1 - b] = (unsigned char)(bits >> (8*b));
    }

    uint32_t *ctx = aligned_alloc(64, 256);
    Desc desc[8];

    // correctness vs SHA256
    for (int w = 0; w < 8; w++)
        for (int lane = 0; lane < 8; lane++)
            ctx[w*8 + lane] = IV[w];
    for (int i = 0; i < 8; i++) {
        desc[i].ptr = bufs[i];
        desc[i].blocks = blocks;
        desc[i].pad = 0;
    }
    sha256_multi_block(ctx, desc, 8);

    int all_ok = 1;
    for (int lane = 0; lane < 8; lane++) {
        unsigned char out[32];
        SHA256(bufs[lane], msg, out); // hash original msg only — but we overwrote? No, SHA256 reads msg bytes which are intact, padding is after msg.
        // Wait SHA256 will read only msg bytes. Good.
        // But our buffer's first `msg` bytes are the message. SHA256(bufs[lane], msg) is correct.
        unsigned char mine[32];
        for (int w = 0; w < 8; w++) {
            uint32_t v = ctx[w*8 + lane];
            mine[w*4+0] = v >> 24;
            mine[w*4+1] = v >> 16;
            mine[w*4+2] = v >> 8;
            mine[w*4+3] = v;
        }
        if (memcmp(out, mine, 32) != 0) {
            all_ok = 0;
            printf("lane %d DIFF\n", lane);
            printf(" ref "); for (int i=0;i<32;i++) printf("%02x", out[i]); printf("\n");
            printf(" mine "); for (int i=0;i<32;i++) printf("%02x", mine[i]); printf("\n");
        }
    }
    printf("correct: %s\n", all_ok ? "YES" : "NO");

    int reps = 3;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int w = 0; w < 8; w++)
            for (int lane = 0; lane < 8; lane++)
                ctx[w*8 + lane] = IV[w];
        for (int i = 0; i < 8; i++) desc[i].blocks = blocks;
        sha256_multi_block(ctx, desc, 8);
    }
    double t1 = now();
    double mb_bytes = (double)reps * lanes * msg;
    printf("multi8: %.2f ms/msg-equivalent  throughput %.1f MB/s (%.2f ms wall for 8 msgs)\n",
           (t1-t0)/reps/lanes*1000, mb_bytes/(t1-t0)/1e6, (t1-t0)/reps*1000);

